/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.function.Predicate;
import java.util.regex.Pattern;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.gateway.ObservedFingerprintRuleFilter;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.gateway.ObservedFingerprintRuleQueryRepositoryGateway;

/**
 * Fingerprint rules (observed-fingerprint-rule) in memory: they correct the automatic grouping
 * before the fingerprint is computed. Reloaded every minute by the scheduler and shortly after a
 * rule changes; an invalid or too long pattern is skipped with a warning.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class FingerprintRules {

  /** A rule ready to apply. */
  public record Rule(String uid, String originUid, String field, Pattern pattern, String effect,
      String groupKey) {

    boolean applies(final String origin) {
      return null == originUid || originUid.equals(origin);
    }
  }

  /**
   * What the rules decide for an event: drop it, or the event to fingerprint and the frames to
   * skip.
   */
  public record Decision(boolean drop, ErrorEvent event, Predicate<String> ignoreFrame) {}

  private final ObservedFingerprintRuleQueryRepositoryGateway rules;
  private volatile List<Rule> current = List.of();

  public List<Rule> all() {
    return current;
  }

  /** For the tests: the rules to apply. */
  public void set(final List<Rule> rules) {
    this.current = List.copyOf(rules);
  }

  public void reload() {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      current = rules.list(ObservedFingerprintRuleFilter.builder().build()).stream()
          .filter(rule -> Boolean.TRUE.equals(rule.isEnabled())).map(this::toRule)
          .flatMap(Optional::stream).toList();
    } catch (RuntimeException ex) {
      log.warn("Unable to reload the fingerprint rules: {}", ex.getMessage());
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }

  private Optional<Rule> toRule(final ObservedFingerprintRule rule) {
    Optional<Pattern> pattern = SafeRegex.compile(rule.getPattern());
    if (pattern.isEmpty()) {
      log.warn("The fingerprint rule {} has an invalid or too long pattern: it is not applied",
          rule.getName());
      return Optional.empty();
    }
    return Optional
        .of(new Rule(rule.getUid(), rule.getOriginUid().orElse(null), value(rule.getField()),
            pattern.get(), value(rule.getEffect()), rule.getGroupKey().orElse(null)));
  }

  /** Applies the rules of the origin to an event. */
  public static Decision apply(final List<Rule> rules, final String originUid,
      final ErrorEvent event) {
    ErrorEvent result = event;
    Predicate<String> ignore = frame -> false;
    for (Rule rule : rules) {
      if (!rule.applies(originUid)) {
        continue;
      }
      if ("ignore-frame".equals(rule.effect())) {
        Predicate<String> previous = ignore;
        ignore = frame -> previous.test(frame) || SafeRegex.find(rule.pattern(), frame);
        continue;
      }
      boolean matches = "frame".equals(rule.field())
          ? null != event.stack() && SafeRegex.find(rule.pattern(), event.stack())
          : SafeRegex.find(rule.pattern(),
              "type".equals(rule.field()) ? event.type() : event.message());
      if (!matches) {
        continue;
      }
      if ("drop".equals(rule.effect())) {
        return new Decision(true, event, ignore);
      }
      if ("group-as".equals(rule.effect()) && result == event) {
        String key =
            null == rule.groupKey() || rule.groupKey().isBlank() ? rule.uid() : rule.groupKey();
        result = new ErrorEvent(event.source(), event.ts(), event.level(), event.type(),
            event.message(), event.stack(), event.traceId(), sha1("rule\n" + key), event.release(),
            event.context());
      }
    }
    return new Decision(false, result, ignore);
  }

  static String value(final Enum<?> option) {
    return null == option ? null : option.name().toLowerCase(Locale.ROOT).replace('_', '-');
  }

  private static String sha1(final String value) {
    try {
      return HexFormat.of().formatHex(
          MessageDigest.getInstance("SHA-1").digest(value.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
